"use client"

import React from "react"
import * as AccordionPrimitive from "@radix-ui/react-accordion"
import { ChevronDownIcon } from "lucide-react"
import { cn as classNames } from "@/lib/utils"

type BaseProps = AccordionContextType & {
	className?: string
	children: React.ReactNode
	ref?: React.Ref<HTMLDivElement>
}

type AccordionSingleProps = {
	interaction?: "single"
	collapsible?: boolean
} & Omit<AccordionPrimitive.AccordionSingleProps, "type" | "collapsible"> &
	BaseProps

type AccordionMultipleProps = {
	interaction: "multiple"
} & Omit<AccordionPrimitive.AccordionMultipleProps, "type"> &
	BaseProps

type AccordionContextType = {
	size?: "sm" | "lg"
	variant?: "box" | "table" | "open"
}

export type AccordionProps = AccordionSingleProps | AccordionMultipleProps

export type AccordionItemProps = React.ComponentProps<typeof AccordionPrimitive.Item> & {
	className?: string
}
export type AccordionTriggerProps = React.ComponentProps<typeof AccordionPrimitive.Trigger> & {
	className?: string
}
export type AccordionContentProps = React.ComponentProps<typeof AccordionPrimitive.Content> & {
	className?: string
}

const AccordionContext = React.createContext<AccordionContextType | null>(null)

function useAccordion() {
	const context = React.useContext(AccordionContext)
	if (!context) {
		throw new Error("useAccordion must be used within a <Accordion />")
	}
	return context
}

function Accordion({ size = "sm", variant = "box", interaction = "single", className, children, ...rest }: AccordionProps) {
	const rootProps =
		interaction === "single"
			? {
					...(rest as AccordionPrimitive.AccordionSingleProps),
					type: "single" as const,
					collapsible: (rest as AccordionSingleProps).collapsible ?? true,
				}
			: {
					...(rest as AccordionPrimitive.AccordionMultipleProps),
					type: "multiple" as const,
				}

	const contextValue = React.useMemo(() => ({ size, variant }), [size, variant])

	return (
		<AccordionContext.Provider value={contextValue}>
			<AccordionPrimitive.Root
				data-slot="accordion"
				className={classNames("w-full", size === "sm" ? "text-sm/6" : "text-base/7", variant === "table" && "border-stroke rounded-xl border", className)}
				{...rootProps}>
				{children}
			</AccordionPrimitive.Root>
		</AccordionContext.Provider>
	)
}
Accordion.displayName = "Accordion"

function AccordionItem({ children, className, ...props }: AccordionItemProps) {
	const { variant, size } = useAccordion()
	let variantClass = ""
	if (variant === "box") {
		variantClass = size === "sm" ? "border-stroke shadow-2xs mb-1.5 rounded-md border last:mb-0" : "border-stroke shadow-2xs mb-2 rounded-md border last:mb-0"
	} else {
		variantClass = "border-b first:rounded-t-xl last:rounded-b-xl last:border-b-0"
	}
	return (
		<AccordionPrimitive.Item data-slot="accordion-item" className={classNames("overflow-hidden", variantClass, className)} {...props}>
			{children}
		</AccordionPrimitive.Item>
	)
}

AccordionItem.displayName = "AccordionItem"

function AccordionTrigger({ children, className, ...props }: AccordionTriggerProps) {
	const { size, variant } = useAccordion()
	let paddingClass = ""
	if (variant === "open") {
		paddingClass = size === "sm" ? "px-0 py-3" : "px-0 py-4"
	} else {
		paddingClass = size === "sm" ? "px-4 py-3" : "p-4"
	}
	return (
		<AccordionPrimitive.Header className="flex">
			<AccordionPrimitive.Trigger
				data-slot="accordion-trigger"
				className={classNames(
					"bg-bg1 text-fg1 outline-hidden flex flex-1 cursor-pointer items-center justify-between text-left font-medium transition-all [&[data-state=open]>.AccordionChevron]:rotate-180",
					paddingClass,
					className
				)}
				{...props}>
				{children}
				<ChevronDownIcon
					className={classNames("AccordionChevron text-text-tertiary shrink-0 transition-transform duration-200", size === "sm" ? "size-5" : "size-6")}
					aria-hidden
				/>
			</AccordionPrimitive.Trigger>
		</AccordionPrimitive.Header>
	)
}

AccordionTrigger.displayName = "AccordionTrigger"

function AccordionContent({ children, className, ...props }: AccordionContentProps) {
	const { size, variant } = useAccordion()
	let paddingClass = ""
	if (variant === "open") {
		paddingClass = size === "sm" ? "px-0 pb-3" : "px-0 pb-4"
	} else {
		paddingClass = size === "sm" ? "px-4 pb-3" : "p-4"
	}
	return (
		<AccordionPrimitive.Content
			data-slot="accordion-content"
			className={classNames("text-text-secondary data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down overflow-hidden transition-all", className)}
			{...props}>
			<div className={classNames(paddingClass, "pt-0")}>{children}</div>
		</AccordionPrimitive.Content>
	)
}

AccordionContent.displayName = "AccordionContent"

export { Accordion, AccordionContent, AccordionItem, AccordionTrigger }

import React from "react"
import { type VariantProps, cva } from "class-variance-authority"
import { cn } from "@/lib/utils"

export type AlertProps = React.HTMLAttributes<HTMLDivElement> &
	VariantProps<typeof alertVariants> & {
		title?: string
		message?: string
		icon?: React.ReactNode
		endContent?: React.ReactNode
		children?: React.ReactNode
	}

export const alertVariants = cva("w-full rounded-xl p-4 flex items-center justify-center gap-3", {
	variants: {
		color: {
			neutral: "bg-fill-level2",
			primary: "border-primary bg-primary/10 text-primary-text",
			info: "border-info bg-info/10 text-info-text",
			success: "border-success bg-success/10 text-success-text",
			danger: "border-error bg-error/10 text-error-text",
			warning: "border-warning bg-warning/10 text-warning-text",
		},
		variant: {
			default: "",
			bordered: "border bg-transparent",
			strong: "",
			"neutral-outline": "border border-border bg-transparent",
		},
	},
	defaultVariants: {
		color: "neutral",
		variant: "default",
	},
	compoundVariants: [
		{
			color: "neutral",
			variant: "bordered",
			className: "border bg-transparent",
		},
		{
			color: "primary",
			variant: "strong",
			className: "bg-primary text-static-white",
		},
		{
			color: "info",
			variant: "strong",
			className: "bg-info text-static-white",
		},
		{
			color: "success",
			variant: "strong",
			className: "bg-success text-static-white",
		},
		{
			color: "warning",
			variant: "strong",
			className: "bg-warning text-static-white",
		},
		{
			color: "danger",
			variant: "strong",
			className: "bg-error text-static-white",
		},
		{
			color: "neutral",
			variant: "strong",
			className: "bg-text text-inverse-white",
		},
	],
})

function Alert({ color = "neutral", variant = "default", title, message, icon, endContent, className, children, ...props }: AlertProps) {
	const isNeutralOutline = variant === "neutral-outline"
	const hasCustomTextColor = className?.includes("text-")

	// Check if we're using the children pattern
	const hasChildrenOnly = children && !title && !message

	return (
		<div className={cn(alertVariants({ color, variant }), className)} {...props}>
			{icon && <div className="flex-shrink-0">{icon}</div>}

			{hasChildrenOnly ? (
				// Render children directly when no title/message provided
				<div className="flex-grow text-sm">{children}</div>
			) : (
				// Original title/message structure
				<div className="flex flex-grow flex-col">
					{title && <h5 className={cn("text-sm font-semibold", isNeutralOutline && "text-text", isNeutralOutline && hasCustomTextColor && "!text-current")}>{title}</h5>}
					{message && <p className={cn("text-sm", isNeutralOutline && "text-text-secondary", isNeutralOutline && hasCustomTextColor && "!text-current opacity-80")}>{message}</p>}
					{children}
				</div>
			)}

			{endContent && <div className="flex-shrink-0">{endContent}</div>}
		</div>
	)
}

export { Alert }

"use client"

import { useState } from "react"
import { Slot } from "@radix-ui/react-slot"
import { type VariantProps, cva } from "class-variance-authority"
import { X } from "lucide-react"
import { cn } from "@/lib/utils"

type BadgeSize = "20" | "24" | "28"

type BadgeProps = React.HTMLAttributes<HTMLDivElement> &
	Omit<VariantProps<typeof badgeVariants>, "size"> & {
		closable?: boolean
		size?: BadgeSize
		className?: string
		color?: "primary" | "info" | "success" | "error" | "warning"
		asChild?: boolean
	}

const badgeVariants = cva("inline-flex items-center font-medium box-border w-fit whitespace-nowrap transition duration-200", {
	variants: {
		variant: {
			neutral: "border border-border-alpha text-text-secondary",
			strong: "",
			outline: "",
			soft: "",
		},
		size: {
			"20": "h-5 px-1.5 text-xs rounded-sm",
			"24": "h-6 px-2 text-xs rounded-sm",
			"28": "h-7 px-2 text-sm rounded-md",
		},
		color: {
			primary: "",
			info: "",
			success: "",
			error: "",
			warning: "",
		},
	},
	defaultVariants: {
		variant: "neutral",
		size: "24",
		color: "primary",
	},
	compoundVariants: [
		// Strong variant + colors
		{
			variant: "strong",
			color: "primary",
			className: "bg-primary text-static-white font-semibold",
		},
		{
			variant: "strong",
			color: "info",
			className: "bg-info text-static-white font-semibold",
		},
		{
			variant: "strong",
			color: "success",
			className: "bg-success text-static-white font-semibold",
		},
		{
			variant: "strong",
			color: "error",
			className: "bg-error text-static-white font-semibold",
		},
		{
			variant: "strong",
			color: "warning",
			className: "bg-warning text-static-white font-semibold",
		},

		// Outline variant + colors
		{
			variant: "outline",
			color: "primary",
			className: "text-primary-text border border-primary bg-transparent",
		},
		{
			variant: "outline",
			color: "info",
			className: "text-info-text border border-info bg-transparent",
		},
		{
			variant: "outline",
			color: "success",
			className: "text-success-text border border-success bg-transparent",
		},
		{
			variant: "outline",
			color: "error",
			className: "text-error-text border border-error bg-transparent",
		},
		{
			variant: "outline",
			color: "warning",
			className: "text-warning-text border border-warning bg-transparent",
		},

		// Soft variant + colors
		{
			variant: "soft",
			color: "primary",
			className: "bg-primary-accent text-primary-text",
		},
		{
			variant: "soft",
			color: "info",
			className: "bg-info-accent text-info-text",
		},
		{
			variant: "soft",
			color: "success",
			className: "bg-success-accent text-success-text",
		},
		{
			variant: "soft",
			color: "error",
			className: "bg-error-accent text-error-text",
		},
		{
			variant: "soft",
			color: "warning",
			className: "bg-warning-accent text-warning-text",
		},
	],
})

function Badge({ variant = "neutral", size = "24", color = "primary", closable = false, className, asChild = false, children, ...props }: BadgeProps) {
	const [showBadge, setShowBadge] = useState(true)
	const Comp = asChild ? Slot : "div"

	if (!showBadge) return null

	// Wrap content in a single span if asChild is true
	const content = (
		<>
			{Array.isArray(children)
				? children.map((child, index) =>
						typeof child === "object" && child !== null && "type" in child && (child.type === "svg" || typeof child.type === "function") ? <span key={index}>{child}</span> : child
					)
				: children}
			{closable && (
				<X
					onClick={() => setShowBadge(false)}
					className={cn(size === "20" || size === "24" ? "size-3" : "size-4", "cursor-pointer font-extrabold", variant === "neutral" && "text-text-disabled")}
				/>
			)}
		</>
	)

	return (
		<Comp className={cn(badgeVariants({ variant, size, color }), "flex items-center gap-1", className)} {...props}>
			{asChild ? <span className="contents">{content}</span> : content}
		</Comp>
	)
}

Badge.displayName = "Badge"

export { Badge }

"use client"

import { HTMLAttributes, ReactNode, useState } from "react"
import { VariantProps, cva } from "class-variance-authority"
import { X } from "lucide-react"
import { cn } from "@/lib/utils"

type BannerProps = HTMLAttributes<HTMLDivElement> &
	VariantProps<typeof bannerVariants> & {
		children: ReactNode
		variant?: "primary" | "outline" | "gray" | "destructive"
		closable?: boolean
		className?: string
	}

const bannerVariants = cva("py-2 px-4 flex items-center justify-center gap-2.5 relative text-sm w-full", {
	variants: {
		variant: {
			gray: "bg-fill-level2",
			primary: "bg-primary text-static-white",
			outline: "bg-base  border-b",
			destructive: "bg-error text-static-white",
		},
	},
	defaultVariants: {
		variant: "gray",
	},
})

function Banner({ children, variant = "gray", closable, className = "", ...props }: BannerProps) {
	const [showBanner, setShowBanner] = useState(true)
	function getClosableVariant() {
		if (["primary", "destructive"].includes(variant)) {
			return "text-static-white"
		}
		if (["outline", "gray"].includes(variant)) {
			return "text-text-disabled"
		}
	}

	return (
		showBanner && (
			<div {...props} className={cn(bannerVariants({ variant }), className)}>
				{children}
				{closable && <X size={20} onClick={() => setShowBanner(false)} className={`${getClosableVariant()} absolute right-4 cursor-pointer`} />}
			</div>
		)
	)
}
export { Banner }

"use client"

import React, { useEffect, useState } from "react"
import { ChevronRight, Ellipsis } from "lucide-react"
import Link from "next/link"
import { cn } from "@/lib/utils"
import { Badge } from "./badge"
import { Dropdown, DropdownContent, DropdownGroup, DropdownItem, DropdownTrigger } from "./dropdown"

type BaseProps = React.HTMLAttributes<HTMLElement> & {
	className?: string
	children?: React.ReactNode
}

type BreadcrumbProps = BaseProps & {
	separator?: "default" | "slash"
	maxItems?: number
}

type BreadcrumbItemProps = BaseProps & {
	href?: string
	isCurrent?: boolean
	showSeparator?: boolean
	separator?: "default" | "slash"
}

function Breadcrumb({ children, className = "", separator = "default", maxItems: maxItemsProp = 5, ...props }: BreadcrumbProps) {
	const [maxItems, setMaxItems] = useState(maxItemsProp)

	useEffect(() => {
		const handleResize = () => {
			setMaxItems(window.innerWidth <= 640 ? 2 : window.innerWidth <= 768 ? 3 : window.innerWidth <= 1024 ? 4 : maxItemsProp)
		}

		handleResize()
		window.addEventListener("resize", handleResize)
		return () => window.removeEventListener("resize", handleResize)
	}, [maxItemsProp])

	const childArray = React.Children.toArray(children)
	const shouldShowEllipsis = childArray.length > maxItems
	const visibleItems = shouldShowEllipsis ? [childArray[0], ...childArray.slice(-maxItems + 1)] : childArray
	const invisibleItems = shouldShowEllipsis ? childArray.slice(1, -maxItems + 1) : []

	return (
		<nav className={cn("flex items-center", className)} {...props}>
			<ol className="flex items-center justify-center gap-1.5">
				{visibleItems.map((child, index, array) => {
					if (!React.isValidElement<BreadcrumbItemProps>(child)) return child

					const isLast = index === array.length - 1
					const showEllipsis = shouldShowEllipsis && index === 0

					return (
						<React.Fragment key={child.key ?? index}>
							{React.cloneElement(child, {
								...child.props,
								showSeparator: !isLast || showEllipsis,
								separator,
							})}
							{showEllipsis && (
								<>
									<BreadcrumbItem className="cursor-default hover:no-underline">
										<Dropdown>
											<DropdownTrigger asChild>
												<Badge className="cursor-pointer" size="20">
													<Ellipsis size={16} />
												</Badge>
											</DropdownTrigger>
											<DropdownContent>
												<DropdownGroup>
													{invisibleItems.map((hiddenChild, hiddenIndex) =>
														React.isValidElement<BreadcrumbItemProps>(hiddenChild) ? (
															<DropdownItem key={hiddenChild.key ?? hiddenIndex}>
																<Link className="flex items-center justify-start gap-0.5" href={hiddenChild.props.href || "#"}>
																	{hiddenChild.props.children}
																</Link>
															</DropdownItem>
														) : null
													)}
												</DropdownGroup>
											</DropdownContent>
										</Dropdown>
									</BreadcrumbItem>
									{separator === "slash" ? <span className="text-text-tertiary text-sm">/</span> : <ChevronRight size={14} className="stroke-text-tertiary" />}
								</>
							)}
						</React.Fragment>
					)
				})}
			</ol>
		</nav>
	)
}
Breadcrumb.displayName = "Breadcrumb"

function BreadcrumbItem({ children, href, isCurrent = false, className = "", showSeparator = false, separator = "default", ...props }: BreadcrumbItemProps) {
	return (
		<>
			<li className="flex items-center justify-center" {...props}>
				{href ? (
					<Link
						href={href}
						className={cn(
							"flex items-center gap-1 text-sm font-medium transition-colors",
							isCurrent ? "font-medium" : "text-text-secondary",
							"hover:underline",
							"[&>svg]:h-full [&>svg]:max-h-5 [&>svg]:w-auto",
							className
						)}>
						{children}
					</Link>
				) : (
					<span
						className={cn(
							"flex items-center gap-1 text-sm font-medium transition-colors",
							isCurrent ? "font-medium" : "text-text-secondary",
							"[&>svg]:h-full [&>svg]:max-h-5 [&>svg]:w-auto",
							className
						)}>
						{children}
					</span>
				)}
			</li>
			{showSeparator && (separator === "slash" ? <span className="text-text-tertiary text-sm">/</span> : <ChevronRight size={14} className="stroke-text-tertiary" />)}
		</>
	)
}

BreadcrumbItem.displayName = "BreadcrumbItem"

export { Breadcrumb, BreadcrumbItem }

"use client"

import React from "react"
import { Slot } from "@radix-ui/react-slot"
import { type VariantProps, cva } from "class-variance-authority"
import { cn } from "@/lib/utils"
import { Spinner } from "./spinner"

type ButtonProps = VariantProps<typeof buttonVariants> &
	React.ButtonHTMLAttributes<HTMLButtonElement> & {
		className?: string
		children: React.ReactNode
		iconOnly?: boolean
		color?: "primary" | "info" | "success" | "error" | "warning" | "neutral"
		lead?: React.ReactNode
		trail?: React.ReactNode
		loading?: boolean
		asChild?: boolean
	}

type ButtonGroupProps = React.HTMLAttributes<HTMLDivElement> & {
	children: React.ReactNode
	variant?: ButtonProps["variant"]
	size?: ButtonProps["size"]
	color?: ButtonProps["color"]
}

type CompactButtonProps = Omit<ButtonProps, "iconOnly" | "lead" | "trail" | "size"> & {
	size?: "20" | "24"
	asChild?: boolean
}

export const buttonVariants = cva(
	"inline-flex whitespace-nowrap items-center justify-center box-border transition-colors duration-200 transform focus-visible:ring-2 focus-visible:outline-none focus-visible:ring-offset-2 focus-visible:ring-offset-bg-base disabled:pointer-events-none hover:cursor-pointer w-fit",
	{
		variants: {
			variant: {
				strong: "",
				soft: "",
				outline: "",
				ghost: "",
			},
			size: {
				"28": "[&>svg]:size-4 text-xs/4 px-1 rounded-md",
				"32": "[&>svg]:size-5 text-sm px-1 rounded-lg",
				"36": "[&>svg]:size-5 text-sm px-1 rounded-lg",
				"40": "[&>svg]:size-5 text-sm px-1 rounded-lg",
				"44": "[&>svg]:size-6 text-base px-1 rounded-lg",
				"48": "[&>svg]:size-6 text-base px-1 rounded-lg",
			},
			loading: {
				true: "",
				false: "",
			},

			iconOnly: {
				true: "",
				false: "",
			},
			color: {
				primary: "",
				info: "",
				success: "",
				error: "",
				warning: "",
				neutral: "[&>svg]:text-text-secondary",
			},
		},
		defaultVariants: {
			variant: "strong",
			size: "36",
			iconOnly: false,
			color: "primary",
			loading: false,
		},
		compoundVariants: [
			// Size variants
			{ iconOnly: false, size: "28", className: "gap-2 h-7 px-2" },
			{ iconOnly: false, size: "32", className: "gap-2 h-8 px-2.5" },
			{ iconOnly: false, size: "36", className: "gap-2 h-9 px-3" },
			{ iconOnly: false, size: "40", className: "gap-2 h-10 px-3.5" },
			{ iconOnly: false, size: "44", className: "gap-2 h-11 px-4" },
			{ iconOnly: false, size: "48", className: "gap-2 h-12 px-4.5" },

			{ iconOnly: true, size: "28", className: "px-1.5 h-7 gap-2" },
			{ iconOnly: true, size: "32", className: "px-1.5 h-8 gap-2" },
			{ iconOnly: true, size: "36", className: "px-2 h-9 gap-2" },
			{ iconOnly: true, size: "40", className: "px-2.5 h-10 gap-2" },
			{ iconOnly: true, size: "44", className: "px-2.5 h-11 gap-2" },
			{ iconOnly: true, size: "48", className: "px-3 h-12 gap-2" },

			// Strong variant + colors
			{
				variant: "strong",
				color: "primary",
				className: "bg-primary font-medium text-static-white hover:bg-primary-hover focus-visible:ring-primary focus-visible:outline-none",
			},
			{
				variant: "strong",
				color: "info",
				className: "bg-info font-medium text-static-white hover:bg-info-hover focus-visible:ring-info focus-visible:outline-none",
			},
			{
				variant: "strong",
				color: "success",
				className: "bg-success font-medium text-static-white hover:bg-success-hover focus-visible:ring-success focus-visible:outline-none",
			},
			{
				variant: "strong",
				color: "error",
				className: "bg-error font-medium text-static-white hover:bg-error-hover focus-visible:ring-error focus-visible:outline-none",
			},
			{
