}

export default DatePicker

function TypeableDatePicker({
	size,
	label,
	rounded,
	disables,
	hasError,
	classNames,
	components,
	navigatorStyle = "button",
	showTime = false,
	dualCalendar = false,
	className,
	footer,
	showDateRangeShortcut,
	onSelectTime,
	hint,
	time,
	onChange, // Add this prop
	value, // Add this prop for controlled component
	...props
}: DatePickerProps & {
	onChange?: (dateTime: ZonedDateTime | null) => void
	value?: ZonedDateTime | null
}) {
	const mergedClassName = cn(`p-3 bg-bg-level1 ${showTime ? " border-r" : ""}`, className)
	const hideCaption: boolean = false

	// Use controlled/uncontrolled pattern
	const [internalDateTime, setInternalDateTime] = useState<ZonedDateTime | null>(null)
	const isControlled = value !== undefined
	const dateTime = isControlled ? value : internalDateTime

	// Initialize dateTime from props if provided
	useEffect(() => {
		if (!isControlled && !internalDateTime) {
			// Try to create initial dateTime from props
			const today = new Date()
			const initialHour = time?.hour || 0
			const initialMinute = time?.minute || 0

			const isoString =
				`${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, "0")}-${String(today.getDate()).padStart(2, "0")}` +
				`T${String(initialHour).padStart(2, "0")}:${String(initialMinute).padStart(2, "0")}` +
				`[America/Los_Angeles]`

			try {
				const initialDateTime = parseZonedDateTime(isoString)
				setInternalDateTime(initialDateTime)
			} catch (error) {
				console.error("Failed to parse initial dateTime", error)
			}
		}
	}, [time, isControlled, internalDateTime])

	// Merged class names for styling
	const mergedClassNames = getMergedClassNames({
		props,
		navigatorStyle,
		dualCalendar,
		hideCaption,
		classNames,
	})

	// Merged components including custom ones
	const mergedComponents = {
		Chevron: (props: ChevronProps) => {
			if (props.orientation === "left") return <ChevronLeft size={16} className="stroke-text" />
			return <ChevronRight size={16} className="stroke-text" />
		},
		...components,
	}

	const [selectedIndex, setSelectedIndex] = useState<number | null>(null)

	// Convert to DateValue for DateField
	const dateValue = useMemo(() => {
		if (!dateTime) {
			// If no dateTime but time prop exists, create a dateTime with today's date
			if (time && !dateTime) {
				const today = new Date()
				const isoString =
					`${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, "0")}-${String(today.getDate()).padStart(2, "0")}` +
					`T${String(time.hour).padStart(2, "0")}:${String(time.minute).padStart(2, "0")}` +
					`[America/Los_Angeles]`

				try {
					const tempDateTime = parseZonedDateTime(isoString)
					return new CalendarDateTime(tempDateTime.year, tempDateTime.month, tempDateTime.day, showTime ? tempDateTime.hour : 0, showTime ? tempDateTime.minute : 0)
				} catch (error) {
					console.error("Failed to create dateValue from time prop", error)
					return null
				}
			}
			return null
		}

		return new CalendarDateTime(dateTime.year, dateTime.month, dateTime.day, showTime ? dateTime.hour : 0, showTime ? dateTime.minute : 0)
	}, [dateTime, showTime, time])

	// Modified to call onChange callback
	const handleDateTimeChange = (newDateTime: ZonedDateTime | null) => {
		if (!isControlled) {
			setInternalDateTime(newDateTime)
		}
		onChange?.(newDateTime) // Notify parent of changes

		// Also call onSelectTime if time changes
		if (newDateTime && onSelectTime) {
			const newTime = new Time(newDateTime.hour, newDateTime.minute)
			onSelectTime(newTime)
		}
	}

	// Handle date changes with proper validation
	const handleDateChange = useCallback(
		(value: DateValue | null) => {
			if (!value) {
				handleDateTimeChange(null)
				return
			}

			try {
				// Ensure all date parts are properly formatted
				const year = value.year
				const month = "month" in value ? value.month : dateTime?.month || 1
				const day = "day" in value ? value.day : dateTime?.day || 1
				const hour = showTime && "hour" in value ? value.hour : dateTime?.hour || 0
				const minute = showTime && "minute" in value ? value.minute : dateTime?.minute || 0

				// Construct properly padded ISO string
				const isoString =
					`${String(year).padStart(4, "0")}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}` +
					`T${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}` +
					`[America/Los_Angeles]`

				const newDateTime = parseZonedDateTime(isoString)
				handleDateTimeChange(newDateTime)
			} catch (error) {
				console.error("Invalid date input", error)
			}
		},
		[dateTime, showTime, handleDateTimeChange]
	)

	const sizeHeightMapping = {
		0: "",
		28: "h-4 w-4",
		32: "h-5 w-5",
		36: "h-5 w-5",
		40: "h-5 w-5",
		44: "h-6 w-6",
		48: "h-6 w-6",
	}

	useEffect(() => {
		if (!dateTime) return

		const matchedIndex = timeOptions.findIndex((time) => time.hour === dateTime.hour && time.minute === dateTime.minute)

		if (matchedIndex !== -1 && matchedIndex !== selectedIndex) {
			setSelectedIndex(matchedIndex)
		}
	}, [dateTime, selectedIndex])

	// Update selectedIndex when time prop changes
	useEffect(() => {
		if (time && timeOptions) {
			const matchedIndex = timeOptions.findIndex((option) => option.hour === time.hour && option.minute === time.minute)
			if (matchedIndex !== -1) {
				setSelectedIndex(matchedIndex)
			}
		}
	}, [time, timeOptions])

	return (
		<Popover>
			<PopoverTrigger disabled={disables} asChild>
				<div className="flex flex-col items-start gap-1.5">
					{label && <Label className={cn({ "text-text-disabled cursor-not-allowed": disables })}>{label}</Label>}
					<div
						className={cn("w-[320px]", dateInputStyles({ size, rounded }), {
							"border-error focus-within:ring-error/10 focus-within:ring-2": hasError && !disables,
							"focus-within:border-primary focus-within:ring-primary/10 border-border-alpha focus-within:ring-2": !hasError && !disables,
							"text-text-disables bg-fill-level1 cursor-not-allowed drop-shadow-none": disables,
						})}>
						<DateField
							granularity={showTime ? "minute" : "day"}
							className={cn("flex flex-col gap-1 border-none")}
							value={dateValue}
							onChange={handleDateChange}
							isDisabled={disables}
							{...props}>
							<DateInputRC>
								{(segment) => (
									<DateSegment
										className={cn(
											size,
											"rounded-sm text-end",
											"data-[focused]:bg-fill-level3",
											"data-placeholder:text-text-tertiary",
											"focus:outline-hidden focus:caret-transparent",
											"data-[type=dayPeriod]:mr-0.5 data-[type=literal]:mr-0.5",
											{
												"text-text-disabled placeholder-text-disabled cursor-not-allowed": disables,
											}
										)}
										segment={segment}
									/>
								)}
							</DateInputRC>
						</DateField>
						<CalendarIcon
							className={cn(sizeHeightMapping[size || 36], "stroke-text-tertiary cursor-pointer", {
								"text-text-tertiary": !disables,
								"text-text-disabled cursor-not-allowed": disables,
							})}
						/>
					</div>
					{hint && <Label className={`flex items-start text-xs font-normal ${hasError ? "text-error" : "text-text-tertiary"}`}>{hint}</Label>}
				</div>
			</PopoverTrigger>

			<PopoverContent className="w-auto border-none p-0">
				<div className="bg-bg-level1 border-border drop-shadow-xs w-fit overflow-hidden rounded-xl border">
					<div className={`flex ${footer ? "border-b" : ""} overflow-hidden`}>
						{showDateRangeShortcut && <DateRangeShortcut mode="single" />}
						<DayPicker
							mode="single"
							numberOfMonths={dualCalendar ? 2 : 1}
							selected={dateTime ? new Date(dateTime.year, dateTime.month - 1, dateTime.day) : undefined}
							month={dateTime ? new Date(dateTime.year, dateTime.month - 1, 1) : new Date()}
							onSelect={(selectedDate) => {
								if (selectedDate) {
									const currentTime = dateTime
										? {
												hour: dateTime.hour,
												minute: dateTime.minute,
											}
										: { hour: 0, minute: 0 }

									const year = selectedDate.getFullYear()
									const month = selectedDate.getMonth() + 1
									const maxDay = new Date(year, month, 0).getDate()
									const day = Math.min(selectedDate.getDate(), maxDay)

									const newDateTime = parseZonedDateTime(
										`${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}` +
											`T${String(currentTime.hour).padStart(2, "0")}:${String(currentTime.minute).padStart(2, "0")}` +
											`[America/Los_Angeles]`
									)

									handleDateTimeChange(newDateTime)
								}
							}}
							className={mergedClassName}
							showOutsideDays
							defaultMonth={dateTime ? new Date(dateTime.year, dateTime.month - 1, 1) : new Date()}
							components={mergedComponents}
							classNames={mergedClassNames}
						/>
						<TimeSelector
							timeOptions={timeOptions}
							selectedIndex={selectedIndex}
							setSelectedIndex={setSelectedIndex}
							formatTime={formatTime}
							showTime={showTime}
							onTimeSelect={(formattedTime) => {
								const [timePart, rawPeriod] = formattedTime.trim().split(" ")
								if (!timePart || !rawPeriod) return

								const period = rawPeriod.toUpperCase() === "PM" ? "PM" : "AM"
								const [hourStr, minuteStr] = timePart.split(":")
								let hour = parseInt(hourStr, 10)
								const minute = parseInt(minuteStr, 10)

								// Convert to 24-hour format
								if (period === "AM" && hour === 12) hour = 0
								if (period === "PM" && hour !== 12) hour += 12

								if (dateTime) {
									const newDateTime = parseZonedDateTime(
										`${dateTime.year}-${String(dateTime.month).padStart(2, "0")}-${String(dateTime.day).padStart(2, "0")}` +
											`T${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}` +
											`[America/Los_Angeles]`
									)
									handleDateTimeChange(newDateTime)
								}
							}}
						/>
					</div>
					<div className="flex w-full justify-end">{footer && footer}</div>
				</div>
			</PopoverContent>
		</Popover>
	)
}

"use client"

import React from "react"
import { type VariantProps, cva } from "class-variance-authority"
import { Drawer as DrawerPrimitives } from "vaul"
import { cn } from "@/lib/utils"

type BackdropType = "overlay" | "blur" | null
type DrawerType = "float" | "default" | "rounded"
type DirectionType = "top" | "bottom" | "right" | "left"

export type DrawerContextType = {
	backdrop: BackdropType
	type: DrawerType
	handle: boolean
	direction: DirectionType
}

type DrawerWrapperProps = VariantProps<typeof drawerVariants> &
	React.ComponentProps<typeof DrawerPrimitives.Root> & {
		backdrop?: BackdropType
		type?: DrawerType
		handle?: boolean
		className?: string
	}

type DrawerHeaderProps = {
	children: React.ReactNode
	className?: string
}

type DrawerTitleProps = {
	children: React.ReactNode
	className?: string
}

type DrawerDescriptionProps = {
	children: React.ReactNode
	className?: string
}

type DrawerFooterProps = {
	children: React.ReactNode
	className?: string
}

type DrawerCloseProps = {
	children: React.ReactNode
}

const drawerVariants = cva("fixed bg-transparent z-[51] bg-base", {
	variants: {
		type: {
			float: "",
			default: "outline outline-border",
			rounded: "rounded-xl", // No outline for rounded type to avoid the border issue
		},
		direction: {
			top: "top-0 w-full h-fit left-0 max-h-full",
			bottom: "bottom-0 left-0 w-full h-fit max-h-full",
			right: "top-0 right-0 h-full w-fit max-w-full",
			left: "top-0 left-0 h-full w-fit max-w-full",
		},
	},
	defaultVariants: {
		direction: "right",
		type: "default",
	},

	compoundVariants: [
		{
			type: "float", // to show gap on all sides
			direction: "top",
			className: "top-2 left-2 w-[calc(100%-1rem)]",
		},
		{
			type: "float",
			direction: "bottom",
			className: "bottom-2 left-2 w-[calc(100%-1rem)]",
		},
		{
			type: "float",
			direction: "left",
			className: "top-2 left-2 h-[calc(100%-1rem)]",
		},
		{
			type: "float",
			direction: "right",
			className: "top-2 right-2 h-[calc(100%-1rem)]",
		},
	],
})

const backdropVariants = cva("z-50 fixed", {
	variants: {
		backdrop: {
			overlay: "inset-0 bg-static-black/50",
			blur: "backdrop-blur-sm inset-0",
		},
	},
	defaultVariants: {
		backdrop: "overlay",
	},
})

const handleVariants = cva("absolute! max-h-20! max-w-1.5! z-50! bg-border! rounded-full!", {
	variants: {
		direction: {
			left: "right-3! top-1/2! -translate-y-1/2! h-full! w-1.5!",
			right: "left-3! top-1/2! -translate-y-1/2! h-full! w-1.5!",
			top: "bottom-3! left-1/2! -translate-x-1/2! h-1.5! w-full! max-w-20!",
			bottom: "top-3! left-1/2! -translate-x-1/2! h-1.5! w-full! max-w-20!",
		},
	},
	defaultVariants: {
		direction: "right",
	},
})

function getContentClass(type: DrawerType, direction: DirectionType) {
	const baseClasses = "bg-bg-base flex flex-col gap-5 overflow-hidden"

	// Handle float type
	if (type === "float") {
		return cn(baseClasses, "rounded-xl shadow-lg outline outline-border")
	}

	// Handle rounded type
	if (type === "rounded") {
		switch (direction) {
			case "top":
				return cn(baseClasses, "outline outline-border rounded-b-xl")
			case "bottom":
				return cn(baseClasses, "outline outline-border rounded-t-xl")
			case "left":
				return cn(baseClasses, "outline outline-border rounded-r-xl")
			case "right":
				return cn(baseClasses, "outline outline-border rounded-l-xl")
			default:
				return baseClasses
		}
	}

	// Default type
	return baseClasses
}

function getPaddingClass(handle: boolean, direction: DirectionType) {
	if (handle) {
		switch (direction) {
			case "top":
				return "pb-7.5 pt-5 pl-5 pr-5"
			case "bottom":
				return "pt-7.5 pb-5 pl-5 pr-5"
			case "left":
				return "pr-7.5 pt-5 pl-5 pb-5"
			case "right":
				return "pl-7.5 pt-5 pb-5 pr-5"
		}
	}
	return "p-5"
}

const DrawerContext = React.createContext<DrawerContextType | null>(null)

function useDrawer() {
	const context = React.use(DrawerContext)
	if (!context) {
		throw new Error("useDrawer must be used within DrawerContext")
	}
	return context
}

function Drawer({ direction = "right", type = "default", children, backdrop = "overlay", handle = false, ...props }: DrawerWrapperProps) {
	const ctxValues = React.useMemo(() => ({ direction, type, backdrop, handle }), [direction, type, backdrop, handle])

	return (
		<DrawerContext value={ctxValues}>
			<DrawerPrimitives.Root direction={direction} {...props}>
				{children}
			</DrawerPrimitives.Root>
		</DrawerContext>
	)
}

function DrawerTrigger({ asChild, children, ...props }: React.ComponentPropsWithRef<typeof DrawerPrimitives.Trigger>) {
	return (
		<DrawerPrimitives.Trigger asChild {...props}>
			{asChild ? children : <span>{children}</span>}
		</DrawerPrimitives.Trigger>
	)
}

function DrawerContent({ children, className, ...props }: React.ComponentPropsWithRef<typeof DrawerPrimitives.Content>) {
	const { backdrop, direction, handle, type } = useDrawer()

	return (
		<DrawerPrimitives.Portal>
			<DrawerPrimitives.Overlay className={cn(backdropVariants({ backdrop }))} />
			<DrawerPrimitives.Content className={cn(drawerVariants({ direction, type }), getPaddingClass(handle, direction), getContentClass(type, direction), className)} {...props}>
				{handle && <DrawerPrimitives.Handle className={cn(handleVariants({ direction }))} />}
				{children}
			</DrawerPrimitives.Content>
		</DrawerPrimitives.Portal>
	)
}

function DrawerHeader({ children, className }: DrawerHeaderProps) {
	return <div className={cn("flex flex-col gap-1", className)}>{children}</div>
}

function DrawerTitle({ children, className }: DrawerTitleProps) {
	return <DrawerPrimitives.Title className={cn("text-lg font-semibold", className)}>{children}</DrawerPrimitives.Title>
}

function DrawerDescription({ children, className }: DrawerDescriptionProps) {
	return <DrawerPrimitives.Description className={cn("text-text-secondary gap-1 text-sm", className)}>{children}</DrawerPrimitives.Description>
}

function DrawerBody({ children, className }: DrawerDescriptionProps) {
	return <div className={cn("no-scrollbar flex-grow overflow-auto", className)}>{children}</div>
}

function DrawerFooter({ children, className }: DrawerFooterProps) {
	return <div className={cn("flex items-end justify-end gap-2", className)}>{children}</div>
}

function DrawerClose({ children }: DrawerCloseProps) {
	return <DrawerPrimitives.Close asChild>{children}</DrawerPrimitives.Close>
}

export { Drawer, DrawerTrigger, DrawerContent, DrawerBody, DrawerClose, DrawerDescription, DrawerFooter, DrawerHeader, DrawerTitle }

