"use client"

import { ComponentPropsWithoutRef, FC, ReactNode, useRef } from "react"
import { MotionValue, motion, useScroll, useTransform } from "motion/react"
import { cn } from "@/lib/utils"

export interface TextRevealProps extends ComponentPropsWithoutRef<"div"> {
	children: string
}

export const TextReveal: FC<TextRevealProps> = ({ children, className }) => {
	const targetRef = useRef<HTMLDivElement | null>(null)
	const { scrollYProgress } = useScroll({
		target: targetRef,
	})

	if (typeof children !== "string") {
		throw new Error("TextReveal: children must be a string")
	}

	const words = children.split(" ")

	return (
		<div ref={targetRef} className={cn("relative z-0 h-[200vh]", className)}>
			<div className={"sticky top-0 mx-auto flex h-[50%] max-w-4xl items-center bg-transparent px-[1rem] py-[5rem]"}>
				<span ref={targetRef} className={"flex flex-wrap p-5 text-2xl font-bold text-black/20 md:p-8 md:text-3xl lg:p-10 lg:text-4xl xl:text-5xl dark:text-white/20"}>
					{words.map((word, i) => {
						const start = i / words.length
						const end = start + 1 / words.length
						return (
							<Word key={i} progress={scrollYProgress} range={[start, end]}>
								{word}
							</Word>
						)
					})}
				</span>
			</div>
		</div>
	)
}

interface WordProps {
	children: ReactNode
	progress: MotionValue<number>
	range: [number, number]
}

const Word: FC<WordProps> = ({ children, progress, range }) => {
	const opacity = useTransform(progress, (value) => {
		return value > range[0] ? 1 : 0.3
	})

	return (
		<span className="xl:lg-3 relative mx-1 lg:mx-1.5">
			<motion.span style={{ opacity: opacity }} className={"text-black dark:text-white"}>
				{children}
			</motion.span>
		</span>
	)
}

import React from "react"
import { Easing, Variants, motion } from "motion/react"

type EaseOption = Easing | [number, number, number, number] // Cubic bezier array must have exactly 4 numbers

type TypingTextProps = {
	texts: string[]
	duration?: number
	deleteSpeed?: number
	delay?: number
	pauseBetween?: number
	ease?: EaseOption
	showCursor?: boolean
	cursorDuration?: number
	cursorChar?: string
	loop?: boolean
	onComplete?: () => void
	as?: React.ElementType
} & React.ComponentProps<"span">

export const TypingText = ({
	texts,
	duration = 0.05,
	deleteSpeed = 0.03,
	pauseBetween = 1.5,
	ease = "linear",
	showCursor = true,
	cursorDuration = 0.8,
	cursorChar = "|",
	loop = true,
	onComplete,
	as: Component = "span",
	...props
}: TypingTextProps) => {
	const [textIndex, setTextIndex] = React.useState(0)
	const [displayedText, setDisplayedText] = React.useState("")
	const [isDeleting, setIsDeleting] = React.useState(false)
	const [isDone, setIsDone] = React.useState(false)

	React.useEffect(() => {
		if (!texts || texts.length === 0) return

		const currentText = texts[textIndex]
		let timeout: NodeJS.Timeout

		if (!isDeleting && displayedText.length < currentText.length) {
			timeout = setTimeout(() => {
				setDisplayedText(currentText.slice(0, displayedText.length + 1))
			}, duration * 1000)
		} else if (isDeleting && displayedText.length > 0) {
			timeout = setTimeout(() => {
				setDisplayedText(currentText.slice(0, displayedText.length - 1))
			}, deleteSpeed * 1000)
		} else if (!isDeleting && displayedText.length === currentText.length) {
			timeout = setTimeout(() => setIsDeleting(true), pauseBetween * 1000)
		} else if (isDeleting && displayedText.length === 0) {
			setIsDeleting(false)
			const next = textIndex + 1
			const hasMore = next < texts.length
			if (hasMore) {
				setTextIndex(next)
			} else if (loop) {
				setTextIndex(0)
			} else {
				setIsDone(true)
				onComplete?.()
			}
		}

		return () => clearTimeout(timeout)
	}, [displayedText, isDeleting, textIndex, texts, duration, deleteSpeed, pauseBetween, loop, onComplete])

	const cursorVariants: Variants = {
		visible: { opacity: 1 },
		hidden: { opacity: 0 },
	}

	const MotionComponent = motion.create(Component, {
		forwardMotionProps: true,
	})

	return (
		<MotionComponent {...props}>
			{displayedText}
			{showCursor && !isDone && (
				<motion.span
					variants={cursorVariants}
					animate="visible"
					transition={{
						duration: cursorDuration,
						repeat: Infinity,
						repeatType: "reverse",
						ease,
					}}>
					{cursorChar}
				</motion.span>
			)}
		</MotionComponent>
	)
}
